import{_ as i,o as n,c as t,a3 as r}from"./chunks/framework.BlfGB29P.js";const h=JSON.parse('{"title":"Plugin-Entwicklung","description":"Technischer Einstieg für Entwickler eigener ATLAS-Plugins.","frontmatter":{"title":"Plugin-Entwicklung","description":"Technischer Einstieg für Entwickler eigener ATLAS-Plugins."},"headers":[],"relativePath":"projects/atlas-plugins/developers/index.md","filePath":"projects/atlas-plugins/developers/index.md","lastUpdated":1792783045000}'),a={name:"projects/atlas-plugins/developers/index.md"};function l(s,e,o,u,d,c){return n(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="plugin-entwicklung" tabindex="-1">Plugin-Entwicklung <a class="header-anchor" href="#plugin-entwicklung" aria-label="Permalink to &quot;Plugin-Entwicklung&quot;">​</a></h1><p>Dieser Bereich führt durch den Entwicklungsweg für eigenständige ATLAS-Plugins: vom Beispielprojekt über Manifest und Runtime bis zur Veröffentlichung. Die Plugin-Verträge entwickeln sich noch; prüfe vor einer Veröffentlichung die aktuelle Vorlage und das Repository-Format.</p><h2 id="empfohlener-ablauf" tabindex="-1">Empfohlener Ablauf <a class="header-anchor" href="#empfohlener-ablauf" aria-label="Permalink to &quot;Empfohlener Ablauf&quot;">​</a></h2><ol><li>Erstelle ein eigenes Repository mit der <a href="./../plugin-template">offiziellen Plugin-Vorlage</a>.</li><li>Definiere eine eindeutige, nach der Veröffentlichung stabile ID und pflege Name, Version, Beschreibung, Assets und benötigte Fähigkeiten im Manifest.</li><li>Entwickle die Plugin-Oberfläche zunächst eigenständig. Die aktuelle Vorlage enthält eine einfache HTML/CSS/JavaScript-Beispielseite.</li><li>Baue Paket und Katalog mit <code>npm run build</code> und prüfe beide mit <code>npm run check</code>.</li><li>Teste den Katalog im ATLAS-Demo-Repository beziehungsweise in der Administration und veröffentliche Änderungen mit einer erhöhten Plugin-Version.</li></ol><h2 id="leitfaden" tabindex="-1">Leitfäden <a class="header-anchor" href="#leitfaden" aria-label="Permalink to &quot;Leitfäden&quot;">​</a></h2><ul><li><a href="./compatibility">Versionen und Kompatibilität</a>: Veröffentlichungsregeln, geprüfte Grenzen, Sicherung und Datenmigration.</li><li><a href="./manifest">Manifest und Fähigkeiten</a>: Metadaten, IDs, Versionen, Assets und Deklarationen.</li><li><a href="./runtime">Runtime und Lebenszyklus</a>: Runtime-Plugin-Vertrag sowie Aktivieren, Deaktivieren und Aufräumen.</li><li><a href="./publishing">Bauen, prüfen und veröffentlichen</a>: Paketgenerator, Katalog, GitHub Actions und Release-Checkliste.</li><li><a href="./../plugin-template">Plugin-Vorlage</a>: Schritt-für-Schritt-Anleitung für das GitHub-Starterprojekt.</li><li><a href="./../repository-format">Repository-Format</a>: Katalogfelder und installierbares Paketformat.</li></ul><h2 id="sicherheitsgrenzen" tabindex="-1">Sicherheitsgrenzen <a class="header-anchor" href="#sicherheitsgrenzen" aria-label="Permalink to &quot;Sicherheitsgrenzen&quot;">​</a></h2><p>Deklariere nur Fähigkeiten, die dein Plugin wirklich verwendet. Eine Deklaration dokumentiert den Zweck des Plugins; sie ist keine Sandbox und gewährt keinen automatischen Zugriff auf Home Assistant oder Atlas-Interna. Fordere Zugangsdaten nicht in Plugin-Dateien an und veröffentliche keine Tokens oder API-Schlüssel.</p><p>Der App-Server installiert geprüfte Repository- und Importpakete im persistenten Plugin-Verzeichnis und stellt statische Webdateien unter <code>/plugin-assets/&lt;slug&gt;/</code> bereit. Beim Öffnen läuft deren JavaScript im Browser; beliebige Node-Module oder Runtime-Hooks werden nicht automatisch registriert. Die Installation ist keine Sandbox: Prüfe Paket und Browsercode vor dem Öffnen.</p>',9)])])}const f=i(a,[["render",l]]);export{h as __pageData,f as default};
